    /* User01Mapper.selectUserNodeAdminCheck */
	SELECT COUNT(*)
	FROM TB_USER A
	     INNER JOIN TB_SITE_NODE B
			ON (
				A.CMPNY_CD = B.CMPNY_CD
			AND A.NODE_CD = B.NODE_CD
	        AND A.SITE_CD = B.SITE_CD
	        AND (A.USER_CD = B.MAIN_ADMIN_CD OR A.USER_CD = B.SUB_ADMIN_CD)
	        )
	WHERE A.CMPNY_CD = #{cmpnyCd}
	  AND A.USER_CD = #{userCd}

/* User01Mapper.selectUserInfoList */ WITH RECURSIVE viewer AS ( SELECT U.CMPNY_CD, U.USER_CD, U.USER_ID, U.AUTH_CD, U.SITE_CD, U.NODE_CD FROM TB_USER U WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.USER_CD = #{gvUserCd} LIMIT 1 ), node_tree AS ( /* 로그인 사용자의 node 부터 시작 */ SELECT N.CMPNY_CD, N.SITE_CD, N.NODE_CD FROM TB_SITE_NODE N INNER JOIN viewer V ON N.CMPNY_CD = V.CMPNY_CD AND N.SITE_CD = V.SITE_CD AND N.NODE_CD = V.NODE_CD
UNION ALL
/* 하위 노드 무한 확장 */ SELECT C.CMPNY_CD, C.SITE_CD, C.NODE_CD FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD ), search_node_tree AS ( /* 검색 조건(소속부서)부터 시작 — 하위부서 조회 옵션 'Y'일 때만 참조 */ SELECT N.CMPNY_CD, N.SITE_CD, N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
UNION ALL
/* 하위 노드 무한 확장 */ SELECT C.CMPNY_CD, C.SITE_CD, C.NODE_CD FROM TB_SITE_NODE C INNER JOIN search_node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD )
SELECT null AS chk , A.CMPNY_CD AS cmpnyCd , A.USER_CD AS userCd , A.USER_ID AS userId , A.USER_NM AS userNm , A.AUTH_CD AS authCd , FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'AUTH_LEVEL', A.AUTH_CD, null) AS authLevel , A.SITE_CD AS siteCd , A.NODE_CD AS nodeCd , A.NODE_CD AS oriNodeCd , FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'NODE', A.SITE_CD, A.NODE_CD) AS nodeNm , C.SITE_NM AS siteNm , A.MBL_NO_ENC AS mblNo , A.EMAIL_ENC AS email , A.BIRTH_DT_ENC AS birthDt , A.GENDER AS gender , A.USE_YN AS useYn , IFNULL(B.SITE_NM_LIST, '') AS siteNmList , A.ACCOUNT_STATUS AS accountStatus , DATE_FORMAT(STR_TO_DATE(A.WITHDRAWAL_DATE, '%Y%m%d'), '%Y-%m-%d') AS withdrawalDate , A.RANK_CD AS rankCd , FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'BAIM_VAL', A.RANK_CD, 'COM007') AS rankNm , A.DEFAULT_SCH_CD AS defaultSchCd FROM TB_USER A LEFT JOIN ( SELECT X.CMPNY_CD, X.USER_CD, GROUP_CONCAT(S.SITE_NM ORDER BY S.SITE_CD SEPARATOR ',') AS SITE_NM_LIST FROM TB_USER_SITE_AUTH X INNER JOIN TB_SITE S ON X.CMPNY_CD = S.CMPNY_CD AND X.SITE_CD = S.SITE_CD WHERE X.USE_YN = 'Y' GROUP BY X.CMPNY_CD, X.USER_CD ) B ON ( B.CMPNY_CD = A.CMPNY_CD AND B.USER_CD = A.USER_CD ) INNER JOIN TB_SITE C ON ( A.CMPNY_CD = C.CMPNY_CD AND A.SITE_CD = C.SITE_CD AND C.USE_YN = 'Y' ) WHERE 1=1 AND A.CMPNY_CD = #{gvCmpnyCd} AND A.AUTH_CD != 'system' /* 시스템관리자 권한 제외(기존 유지) */ AND A.USE_YN = 'Y'
/* 권한별 노드/사이트 제한 */ AND ( (SELECT V.AUTH_CD FROM viewer V) IN ('system','master','hr','safe') OR ( /* 비권한 사용자는 본인 site 고정 + 하위 node만 */ A.SITE_CD = (SELECT V.SITE_CD FROM viewer V)
AND A.NODE_CD IN (SELECT T.NODE_CD FROM node_tree T)
) )
AND ( A.USER_ID LIKE CONCAT('%', #{userKeyword}, '%') OR A.USER_NM LIKE CONCAT('%', #{userKeyword}, '%') )
AND A.USER_NM LIKE CONCAT('%', #{userNm}, '%')
AND A.USER_ID = #{userId}
AND A.USE_YN = #{useYn}
AND A.EMPLOYMENT_TYPE = #{employmentType}
AND A.SITE_CD = #{siteCd}
AND A.NODE_CD IN (SELECT T.NODE_CD FROM search_node_tree T)
AND A.NODE_CD = #{nodeCd}

