/* User01Mapper.selectSiteNodeAdminCandidateLists */ SELECT null AS chk , A.CMPNY_CD AS cmpnyCd , A.USER_CD AS userCd , A.USER_ID AS userId , A.USER_NM AS userNm , A.AUTH_CD AS authCd , FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'AUTH_LEVEL', A.AUTH_CD, null) AS authLevel , A.SITE_CD AS siteCd , A.NODE_CD AS nodeCd , A.NODE_CD AS oriNodeCd , FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'NODE', A.SITE_CD, A.NODE_CD) AS nodeNm , C.SITE_NM AS siteNm , A.MBL_NO_ENC AS mblNo , A.EMAIL_ENC AS email , A.BIRTH_DT_ENC AS birthDt , A.GENDER AS gender , A.USE_YN AS useYn , IFNULL(B.SITE_NM_LIST, '') AS siteNmList , A.ACCOUNT_STATUS AS accountStatus , A.WITHDRAWAL_DATE AS withdrawalDate , A.RANK_CD AS rankCd , FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'BAIM_VAL', A.RANK_CD, 'COM007') AS rankNm , A.DEFAULT_SCH_CD AS defaultSchCd FROM TB_USER A LEFT JOIN ( SELECT A.CMPNY_CD , A.USER_CD , GROUP_CONCAT(B.SITE_NM ORDER BY B.SITE_CD SEPARATOR ',') AS SITE_NM_LIST FROM TB_USER_SITE_AUTH A INNER JOIN TB_SITE B ON ( A.CMPNY_CD = B.CMPNY_CD AND A.SITE_CD = B.SITE_CD ) WHERE A.USE_YN = 'Y' GROUP BY A.CMPNY_CD, A.USER_CD ) B ON B.CMPNY_CD = A.CMPNY_CD AND B.USER_CD = A.USER_CD INNER JOIN TB_SITE C ON ( A.CMPNY_CD = C.CMPNY_CD AND A.SITE_CD = C.SITE_CD AND C.USE_YN = 'Y' ) WHERE 1=1 AND A.CMPNY_CD = #{gvCmpnyCd} AND A.AUTH_CD != '999' /* 시스템관리자 권한 제외 */ AND A.USE_YN = 'Y' AND A.SITE_CD = #{siteCd}
AND A.USER_NM LIKE CONCAT('%', #{userNm}, '%')
AND A.USER_ID = #{userId}
AND NOT EXISTS ( SELECT 1 FROM TB_SITE_NODE N WHERE N.CMPNY_CD = A.CMPNY_CD AND N.SITE_CD = A.SITE_CD AND N.NODE_CD = #{nodeCd} AND ( N.MAIN_ADMIN_CD = A.USER_CD OR N.SUB_ADMIN_CD = A.USER_CD ) )

