/* User01Mapper.selectUserStatutoryLeaveSummary */
SELECT
	COALESCE(SUM(A.GRANT_DAYS), 0) AS grantedSum
	, COALESCE(SUM(A.USED_DAYS), 0) AS usedSum
FROM TB_USER_LEAVE_GRANT A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.USER_CD  = #{userCd}
  AND A.GRANT_TYPE LIKE 'STATUTORY\_%'
  AND A.STATUS IN ('ACTIVE', 'EXHAUSTED')
  AND A.DEL_YN = 'N'

