/* User01Mapper.deleteSiteAuthExceptHome */
UPDATE TB_USER_SITE_AUTH
SET
	USE_YN        = 'N'
	, UPDATE_NO   = #{gvUserCd}
	, UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{cmpnyCd}
  AND USER_CD  = #{userCd}
  AND USE_YN   = 'Y'


      AND SITE_CD <> #{homeSiteCd}


      AND 1 = 1
